### ✅ Example 1 — All 3 Types Together

```python name=example1_all_three_methods.py
class Employee:
    company     = "TechCorp"
    total_hired = 0

    def __init__(self, name, salary, department):
        self.name       = name
        self.salary     = salary
        self.department = department
        Employee.total_hired += 1

    # ─── 🔵 INSTANCE METHOD ───
    # → Has 'self' → can access instance attributes AND class attributes
    def get_details(self):
        return (f"👤 {self.name} | Dept: {self.department} | "
                f"Salary: ₹{self.salary} | Company: {Employee.company}")

    def give_raise(self, percent):
        old_salary    = self.salary
        self.salary  *= (1 + percent / 100)
        print(f"💰 {self.name}'s salary: ₹{old_salary} → ₹{self.salary:.0f}")

    # ─── 🟡 CLASS METHOD ───
    # → Has 'cls' → operates on the class itself, not a specific instance
    @classmethod
    def get_company_info(cls):
        return f"🏢 {cls.company} | Total Hired: {cls.total_hired}"

    @classmethod
    def change_company_name(cls, new_name):
        cls.company = new_name
        print(f"✅ Company renamed to: {cls.company}")

    @classmethod
    def from_csv(cls, csv_string):
        """Alternative constructor — class method used as factory"""
        name, salary, dept = csv_string.split(",")
        return cls(name.strip(), float(salary.strip()), dept.strip())

    # ─── 🔴 STATIC METHOD ───
    # → No self, no cls → pure utility, doesn't need class or instance data
    @staticmethod
    def validate_salary(salary):
        return 20000 <= salary <= 5000000

    @staticmethod
    def calculate_tax(salary):
        if salary <= 250000:    return 0
        elif salary <= 500000:  return (salary - 250000) * 0.05
        else:                   return 12500 + (salary - 500000) * 0.20

# ── Using Instance Methods ──
e1 = Employee("Alice", 75000, "Engineering")
e2 = Employee("Bob",   55000, "Marketing")
print(e1.get_details())
e1.give_raise(10)

# ── Using Class Methods ──
print(Employee.get_company_info())           # through class
print(e1.get_company_info())                 # through instance (works too)
Employee.change_company_name("TechCorp Global")

# Factory method
e3 = Employee.from_csv("Carol, 85000, Design")
print(e3.get_details())

# ── Using Static Methods ──
print(Employee.validate_salary(75000))       # True
print(Employee.validate_salary(10))          # False
print(f"Tax on ₹75000: ₹{Employee.calculate_tax(75000):,.0f}")
```

### ✅ Example 2 — Class Method as Factory (Alternative Constructor)

```python name=example2_classmethod_factory.py
import json
from datetime import datetime

class Product:
    def __init__(self, name, price, category, stock, created_at=None):
        self.name       = name
        self.price      = float(price)
        self.category   = category
        self.stock      = int(stock)
        self.created_at = created_at or datetime.now().strftime("%Y-%m-%d")

    # ─── Factory: from JSON string ───
    @classmethod
    def from_json(cls, json_string):
        data = json.loads(json_string)
        print(f"📄 Creating product from JSON...")
        return cls(
            name     = data['name'],
            price    = data['price'],
            category = data['category'],
            stock    = data['stock']
        )

    # ─── Factory: from CSV row ───
    @classmethod
    def from_csv(cls, csv_row):
        parts = csv_row.split(",")
        print(f"📊 Creating product from CSV...")
        return cls(
            name     = parts[0].strip(),
            price    = parts[1].strip(),
            category = parts[2].strip(),
            stock    = parts[3].strip()
        )

    # ─── Factory: out-of-stock product ───
    @classmethod
    def create_out_of_stock(cls, name, price, category):
        print(f"📦 Creating out-of-stock product...")
        return cls(name=name, price=price, category=category, stock=0)

    def display(self):
        status = "✅ In Stock" if self.stock > 0 else "❌ Out of Stock"
        print(f"  {self.name:20s} ₹{self.price:>10,.2f} | "
              f"{self.category:15s} | Stock: {self.stock:3d} | {status}")

# Create from different sources
p1 = Product("iPhone 15", 79999, "Electronics", 50)

p2 = Product.from_json('{"name":"MacBook","price":125000,"category":"Laptops","stock":20}')

p3 = Product.from_csv("AirPods Pro, 24999, Electronics, 100")

p4 = Product.create_out_of_stock("PS5", 49999, "Gaming")

print("\n📋 Product Catalog:")
for p in [p1, p2, p3, p4]:
    p.display()
```

### ✅ Example 3 — Static Methods as Pure Utility Functions

```python name=example3_static_utilities.py
class MathUtils:
    """A utility class with only static methods — no instance state needed"""

    @staticmethod
    def is_prime(n):
        if n < 2: return False
        for i in range(2, int(n**0.5) + 1):
            if n % i == 0: return False
        return True

    @staticmethod
    def factorial(n):
        if n < 0:  raise ValueError("Factorial not defined for negative numbers")
        if n == 0: return 1
        result = 1
        for i in range(1, n + 1):
            result *= i
        return result

    @staticmethod
    def fibonacci(n):
        if n <= 0: return []
        if n == 1: return [0]
        seq = [0, 1]
        while len(seq) < n:
            seq.append(seq[-1] + seq[-2])
        return seq

    @staticmethod
    def gcd(a, b):
        while b:
            a, b = b, a % b
        return a

class StringUtils:
    @staticmethod
    def is_palindrome(s):
        clean = ''.join(c.lower() for c in s if c.isalnum())
        return clean == clean[::-1]

    @staticmethod
    def word_count(text):
        return len(text.split())

    @staticmethod
    def title_case(text):
        return ' '.join(word.capitalize() for word in text.split())

    @staticmethod
    def mask_email(email):
        user, domain = email.split('@')
        return f"{user[0]}{'*' * (len(user)-2)}{user[-1]}@{domain}"

# Using static methods — no object needed!
print(MathUtils.is_prime(17))           # True
print(MathUtils.factorial(6))           # 720
print(MathUtils.fibonacci(8))           # [0, 1, 1, 2, 3, 5, 8, 13]
print(MathUtils.gcd(48, 18))            # 6

print(StringUtils.is_palindrome("A man a plan a canal Panama"))  # True
print(StringUtils.mask_email("alice.smith@gmail.com"))           # a**********h@gmail.com
print(StringUtils.title_case("hello world from python"))         # Hello World From Python
```

### ✅ Example 4 — Class Method Modifying Class State + Real Pattern

```python name=example4_classmethod_state.py
class Config:
    """Application configuration — class methods for global settings"""

    _debug     = False
    _log_level = "INFO"
    _db_url    = "postgresql://localhost/devdb"
    _instances = 0

    def __init__(self, module_name):
        self.module_name = module_name
        Config._instances += 1

    # ── Read class state ──
    @classmethod
    def is_debug(cls):
        return cls._debug

    @classmethod
    def get_log_level(cls):
        return cls._log_level

    # ── Modify class state ──
    @classmethod
    def enable_debug(cls):
        cls._debug     = True
        cls._log_level = "DEBUG"
        print(f"🔴 Debug mode ENABLED. Log level: {cls._log_level}")

    @classmethod
    def set_production(cls):
        cls._debug     = False
        cls._log_level = "ERROR"
        cls._db_url    = "postgresql://prod-server/proddb"
        print(f"🟢 Production mode set. Log level: {cls._log_level}")

    @classmethod
    def get_stats(cls):
        print(f"📊 Config Stats → Modules: {cls._instances} | "
              f"Debug: {cls._debug} | Log: {cls._log_level}")

    # ── Utility (static) ──
    @staticmethod
    def is_valid_log_level(level):
        return level in ("DEBUG", "INFO", "WARNING", "ERROR", "CRITICAL")

    def info(self):
        print(f"⚙️  Module '{self.module_name}' | Debug: {Config._debug} | "
              f"Log: {Config._log_level} | DB: {Config._db_url}")

# Simulate app startup (dev mode)
Config.enable_debug()
auth_config    = Config("auth")
payment_config = Config("payments")
auth_config.info()

# Switch to production
Config.set_production()
auth_config.info()    # instantly sees new config because it uses class variable

Config.get_stats()
print(Config.is_valid_log_level("TRACE"))  # False
```

### ✅ Example 5 — Choosing the Right Method Type (Refactoring Example)

```python name=example5_refactoring_methods.py
class OrderProcessor:
    TAX_RATE       = 0.18
    MIN_ORDER_AMT  = 100
    orders_processed = 0

    def __init__(self, order_id, customer, items):
        self.order_id  = order_id
        self.customer  = customer
        self.items     = items   # list of (name, price, qty)
        self.status    = "Pending"

    # ── 🔵 INSTANCE METHOD — needs THIS order's data ──
    def calculate_subtotal(self):
        return sum(price * qty for _, price, qty in self.items)

    def calculate_tax(self):
        return self.calculate_subtotal() * OrderProcessor.TAX_RATE

    def calculate_total(self):
        return self.calculate_subtotal() + self.calculate_tax()

    def process(self):
        if self.calculate_subtotal() < OrderProcessor.MIN_ORDER_AMT:
            print(f"❌ Order #{self.order_id}: Below minimum order amount")
            return False
        self.status = "Processed"
        OrderProcessor.orders_processed += 1
        print(f"✅ Order #{self.order_id} processed. Total: ₹{self.calculate_total():.2f}")
        return True

    def print_receipt(self):
        print(f"\n🧾 RECEIPT — Order #{self.order_id}")
        print(f"   Customer : {self.customer}")
        for name, price, qty in self.items:
            print(f"   {name:20s} ₹{price:>8,.2f} × {qty} = ₹{price*qty:>10,.2f}")
        print(f"   {'Subtotal':30s} ₹{self.calculate_subtotal():>10,.2f}")
        print(f"   {'GST (18%)':30s} ₹{self.calculate_tax():>10,.2f}")
        print(f"   {'TOTAL':30s} ₹{self.calculate_total():>10,.2f}")
        print(f"   Status   : {self.status}")

    # ── 🟡 CLASS METHOD — works on class level data ──
    @classmethod
    def get_processed_count(cls):
        return cls.orders_processed

    @classmethod
    def update_tax_rate(cls, new_rate):
        print(f"⚠️  Tax rate changed: {cls.TAX_RATE*100}% → {new_rate*100}%")
        cls.TAX_RATE = new_rate

    # ── 🔴 STATIC METHOD — utility, needs no class or instance data ──
    @staticmethod
    def format_currency(amount):
        return f"₹{amount:,.2f}"

    @staticmethod
    def is_valid_order_id(order_id):
        return order_id.startswith("ORD") and len(order_id) == 8

    @staticmethod
    def apply_coupon(amount, coupon_code):
        discounts = {"SAVE10": 0.10, "SAVE20": 0.20, "FLAT100": None}
        if coupon_code == "FLAT100":
            return max(0, amount - 100)
        discount = discounts.get(coupon_code, 0)
        return amount * (1 - discount)

# Test
o1 = OrderProcessor("ORD10001", "Alice", [
    ("Laptop Bag",  1500, 1),
    ("USB Hub",     800,  2),
    ("Mouse Pad",   300,  3),
])
o2 = OrderProcessor("ORD10002", "Bob", [("Pen", 10, 1)])  # below minimum

o1.process()
o1.print_receipt()
o2.process()

print(f"\n📦 Total orders processed: {OrderProcessor.get_processed_count()}")

# Static methods don't need an instance
print(OrderProcessor.format_currency(12345.6))          # ₹12,345.60
print(OrderProcessor.is_valid_order_id("ORD10001"))     # True
print(OrderProcessor.apply_coupon(5000, "SAVE10"))      # 4500.0
```
